function SoarPanel() { const [pbs, setPbs] = useState([]); const [runs, setRuns] = useState([]); const [pb, setPb] = useState('isolate_host'); const [tg, setTg] = useState(''); const [msg, setMsg] = useState(''); const load = () => { fetch(`${API}/api/soar/playbooks`).then(r => r.json()).then(j => setPbs(j.playbooks || [])).catch(() => { }); fetch(`${API}/api/soar/runs`).then(r => r.json()).then(setRuns).catch(() => { }) }; useEffect(() => { load() }, []); const start = async (appr) => { setMsg(''); try { const r = await fetch(`${API}/api/soar/runs`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ playbook: pb, target: tg, approval_confirmed: appr }) }); const j = await r.json(); if (!r.ok) throw new Error(j.detail || 'failed'); setMsg(j.status === 'pending_approval' ? 'Pending approval — nothing executed.' : `Completed: ${(j.actions || []).join('; ')}`); load() } catch (e) { setMsg(e.message) } }; const approve = async (id) => { try { const r = await fetch(`${API}/api/soar/runs/${id}/approve`, { method: 'POST' }); const j = await r.json(); if (!r.ok) throw new Error(j.detail || 'failed'); setMsg(`Run ${id} completed: ${(j.actions || []).join('; ')}`); load() } catch (e) { setMsg(e.message) } }; return <div className="content"><Panel title="SOAR — approval-gated response"><div style={{ display: 'flex', gap: 8, padding: '12px 18px' }}><select value={pb} onChange={e => setPb(e.target.value)}>{pbs.map(p => <option key={p.name} value={p.name}>{p.name} ({p.target})</option>)}</select><input style={{ flex: 1 }} value={tg} onChange={e => setTg(e.target.value)} placeholder="target: hostname / username / IP" /><button className="primary" onClick={() => start(false)}>Stage</button></div><div className="table">{pbs.filter(p => p.name === pb).map(p => <div className="row" key={p.name}><div><small>{p.use} Steps: {p.steps.join(' → ')}</small></div></div>)}</div>{msg && <div className="callout">{msg} {msg.includes('Pending') && <button className="primary" onClick={() => start(true)}>Approve + execute</button>}</div>}<div className="table">{runs.map(r => <div className="row" key={r.id} ><div><b>#{r.id} {r.playbook} → {r.target}</b><small>{r.status} · {r.result || 'awaiting approval'}</small></div>{r.status === 'pending_approval' && <button className="primary" onClick={(e) => { e.stopPropagation(); approve(r.id) }}>Approve</button>}</div>)}</div></Panel></div> }
function WifiPanel({ setSel }) {
  const [mode, setMode] = useState(() => localStorage.getItem('VEYRA_wifi_mode') || 'mode-a');
  const [profiles, setProfiles] = useState(() => JSON.parse(localStorage.getItem('VEYRA_wifi_profiles') || '{"mode-a":{"name":"Router Mode A","ssid":""},"mode-b":{"name":"Router Mode B","ssid":""}}'));
  const [networks, setNetworks] = useState([]), [current, setCurrent] = useState(null), [hosts, setHosts] = useState([]), [sum, setSum] = useState(null), [sensor, setSensor] = useState('checking'), [msg, setMsg] = useState('');
  const profile = profiles[mode] || profiles['mode-a'];
  const saveProfiles = p => { setProfiles(p); localStorage.setItem('VEYRA_wifi_profiles', JSON.stringify(p)) };
  const loadLan = () => { Promise.all([fetch(`${API}/api/discovery/hosts?limit=200`).then(r => r.json()), fetch(`${API}/api/discovery/summary`).then(r => r.json())]).then(([h, s]) => { setHosts(h || []); setSum(s) }).catch(() => { }) };
  const scan = async () => { setMsg(''); setSensor('checking'); try { const h = await fetch('http://127.0.0.1:8765/health'); if (!h.ok) throw new Error('Local Wi-Fi sensor unavailable'); setSensor('online'); const r = await fetch('http://127.0.0.1:8765/wifi/scan'); const j = await r.json(); setNetworks(j.networks || []); setCurrent(j.current || null); setMsg(`Wi-Fi scan complete: ${(j.networks || []).length} nearby network entries.`) } catch (e) { setSensor('offline'); setMsg('Start/install the VEYRA local Wi-Fi sensor on this computer. The browser cannot access the Wi-Fi radio directly. No Wi-Fi passwords are collected.') } };
  const trust = async (h, v) => { try { const r = await fetch(`${API}/api/discovery/hosts/${h.id}/trust`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ trusted: v }) }); if (r.ok) loadLan() } catch (e) { } };
  useEffect(() => { loadLan(); fetch('http://127.0.0.1:8765/health').then(r => { if (r.ok) setSensor('online') }).catch(() => setSensor('offline')) }, []);
  useEffect(() => localStorage.setItem('VEYRA_wifi_mode', mode), [mode]);
  const modeSsid = (profile.ssid || '').trim().toLowerCase(); const shown = modeSsid ? networks.filter(n => (n.ssid || '').toLowerCase() === modeSsid) : networks;
  return <div className="content"><div className="sectionintro"><div><div className="eyebrow">WI-FI + LAN VISIBILITY</div><h2>Nearby Wi-Fi and your network devices</h2><p>Two separate views: nearby wireless networks and devices actually observed on your selected home/office LAN. Use the device baseline to investigate unexpected access.</p></div><div style={{ display: 'flex', gap: 8, alignItems: 'center' }}><select value={mode} onChange={e => setMode(e.target.value)}><option value="mode-a">{profiles['mode-a']?.name || 'Router Mode A'}</option><option value="mode-b">{profiles['mode-b']?.name || 'Router Mode B'}</option></select><button className="primary" onClick={scan}>Scan nearby Wi-Fi</button></div></div>
    <div className="grid2">
      <Panel title={`Nearby Wi-Fi networks · ${profile.name}`}><div style={{ padding: '12px 18px', display: 'grid', gap: 8 }}><div style={{ display: 'flex', gap: 8 }}><input value={profile.ssid || ''} onChange={e => saveProfiles({ ...profiles, [mode]: { ...profile, ssid: e.target.value } })} placeholder="Expected SSID for this router mode" style={{ flex: 1 }} /><span className={sensor === 'online' ? 'badge' : 'badge critical'}>{sensor === 'online' ? 'SENSOR ONLINE' : 'SENSOR OFFLINE'}</span></div><small>Selected mode filters the expected SSID. The scan itself is read-only metadata: SSID/BSSID/signal/channel/security where the OS provides it.</small></div><div className="table"><div className="wifithead"><span>SSID</span><span>BSSID</span><span>SIGNAL</span><span>CHANNEL</span><span>SECURITY</span></div>{shown.map((n, i) => <div className="row wifi" key={n.bssid || `${n.ssid}-${i}`}><div><b>{n.ssid || '(hidden SSID)'}</b><small>{n.band || 'band unknown'}</small></div><div><small>{n.bssid || '—'}</small></div><div><b>{n.signal_dbm ?? n.signal_percent ?? '—'}{n.signal_dbm != null ? ' dBm' : n.signal_percent != null ? '%' : ''}</b></div><div><small>{n.channel || '—'}</small></div><span className="badge">{n.security || 'Unknown'}</span></div>)}{!shown.length && <div className="empty">No Wi-Fi scan data yet. Click “Scan nearby Wi-Fi”.</div>}</div></Panel>
      <Panel title={`My LAN devices · ${hosts.length} observed`}><div className="callout"><span>Only devices observed on your own LAN/Wi-Fi are shown. <b>UNKNOWN</b> means VEYRA has not yet marked the device as trusted; it is not proof of an intruder.</span></div><div className="table"><div className="wifithead"><span>DEVICE</span><span>IP</span><span>MAC / VENDOR</span><span>LAST SEEN</span><span>BASELINE</span></div>{hosts.map(h => <div className="row wifi" key={h.id} onClick={() => setSel({ kind: 'discovered', item: h })}><div><b>{h.hostname || 'unknown'}</b><small>via {h.source || 'collector'}</small></div><div><b>{h.ip_address}</b></div><div><small>{h.mac || '—'}</small><small>{h.vendor || 'Unknown'}</small></div><div><small>{(h.last_seen || '').slice(0, 16).replace('T', ' ')}</small></div><div style={{ display: 'flex', gap: 5, alignItems: 'center' }}><span className={h.trusted ? 'badge' : 'badge critical'}>{h.trusted ? 'TRUSTED' : 'UNKNOWN'}</span><button onClick={e => { e.stopPropagation(); trust(h, !h.trusted) }}>{h.trusted ? 'Untrust' : 'Trust'}</button></div></div>)}{!hosts.length && <div className="empty">No LAN devices yet. Enroll the endpoint sensor and run discovery.</div>}</div></Panel>
    </div>
    <Panel title="Router mode profiles"><div style={{ padding: 14, display: 'grid', gap: 10, gridTemplateColumns: '1fr 1fr' }}>{['mode-a', 'mode-b'].map(k => <div key={k} style={{ border: '1px solid #1d2734', borderRadius: 8, padding: 12 }}><b>{profiles[k]?.name}</b><input style={{ width: '100%', marginTop: 8 }} value={profiles[k]?.ssid || ''} onChange={e => saveProfiles({ ...profiles, [k]: { ...profiles[k], ssid: e.target.value } })} placeholder="SSID" /></div>)}</div></Panel>
    {msg && <div className="callout">{msg}</div>}
    <Panel title="How VEYRA investigates unauthorized access"><div style={{ padding: 16 }}><ol style={{ color: '#9eb8d4', fontSize: 11, lineHeight: 1.8 }}><li>Select Router Mode A or B from the dropdown.</li><li>Scan nearby Wi-Fi and confirm the expected SSID/BSSID is present.</li><li>Review the separate LAN Devices window for unexpected MAC addresses, hosts and vendors.</li><li>Mark known devices as <b>TRUSTED</b>. Leave unknown devices untrusted until verified.</li><li>Correlate unexpected devices with router association/login logs, DHCP leases and VEYRA login/flow telemetry.</li><li>If an unknown device is confirmed, preserve evidence and investigate the router account/MFA and Wi-Fi security configuration. Do not attempt to attack or disrupt the device.</li></ol></div></Panel>
  </div>
}

createRoot(document.getElementById('root')).render(<App />);
